<section class="section" id="work" aria-labelledby="work-title"><div class="container">${label(3,'대표 작업')}<div class="section-top"><h2 id="work-title">${COPY.workTitle[0]} <em>${COPY.workTitle[1]}</em></h2><p>${COPY.workDescription}</p></div><div class="work-panels">${WORK.map((p,i)=>`<article class="work-panel ${i===0?'active':''}"><button class="work-trigger" aria-expanded="${i===0}" aria-controls="work-${p.id}"><small>${num(i+1)}</small><span>${p.title}</span></button><div class="work-body" id="work-${p.id}" ${i?'inert':''}><div class="mono">${p.period}</div><h3>${p.title}</h3><p class="role">${p.role}</p><div class="work-detail"><div><p class="work-text">${p.problem}</p><div class="work-points"><div><h4>접근</h4><p tabindex="0">${p.solution}</p></div><div><h4>결과</h4><p tabindex="0">${p.outcome}</p></div></div></div>${workUI(p)}</div><div class="tool-chips">${p.technologies.map(t=>`<span>${t}</span>`).join('')}</div>${p.links.map(l=>`<a class="pill" style="margin-top:18px" href="${esc(l.href)}" target="_blank" rel="noopener noreferrer">${l.label==='서비스'?'앱 보기':'개발 기록'} ↗</a>`).join('')}</div></article>`).join('')}</div></div></section>
