<section class="achievements" id="achievements" aria-labelledby="achievements-title"><div class="achievements-sticky"><div class="container">${label(5,'성과')}<h2 id="achievements-title">${COPY.achievementsTitle[0]} <em>${COPY.achievementsTitle[1]}</em></h2><div class="achievement-track">${ACHIEVEMENTS.map((a,i)=>`<article class="achievement-card"><small>${num(i+1)} / ${a.label}</small><h3>${a.title}</h3><p>${a.description}</p><div class="metric"><b data-count="${a.value}" style="font-weight:500">${a.value}</b><span>${a.suffix}</span></div><div class="metric-detail">${a.detail}</div></article>`).join('')}<div class="achievement-card achievement-end">${COPY.continuing}</div></div></div></div></section>
