$('#footer').innerHTML=`<span>© ${CONTACT.year} ${PROFILE.displayName}</span><a href="#hero">맨 위로 ↑</a>`;
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});$$('.reveal').forEach(e=>observer.observe(e));
let lenis=null;if(!reduced){import('https://cdn.jsdelivr.net/npm/lenis@1.3.11/+esm').then(({default:Lenis})=>{lenis=new Lenis({duration:1.05,anchors:true});requestAnimationFrame(function tick(t){lenis.raf(t);requestAnimationFrame(tick)})}).catch(()=>{});}
function selectSkill(index){const s=skillList.find(s=>s.index===index);const related=WORK.filter(p=>p.technologies.includes(s.name));$('#skill-info').innerHTML=`<div class="skill-glyph" aria-hidden="true">${SKILL_LOGOS[s.name]?`<img src="${SKILL_LOGOS[s.name]}" width="34" height="34" alt="">`:s.symbol}</div><h3>${s.name}</h3><p>${s.category}</p>${related.length?`<p>관련 작업</p><ul>${related.map(p=>`<li><a href="#work">${p.title}</a></li>`).join('')}</ul>`:'<p>이력서에 기재된 기술입니다.</p>'}`;$$('.element').forEach(e=>e.classList.toggle('selected',+e.dataset.skill===index))}selectSkill(3);
$$('.element').forEach(e=>{e.addEventListener('pointerenter',()=>selectSkill(+e.dataset.skill));e.addEventListener('focus',()=>selectSkill(+e.dataset.skill));e.addEventListener('click',()=>selectSkill(+e.dataset.skill))});$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{$$('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});$$('.element').forEach(e=>e.hidden=b.dataset.filter!=='전체'&&e.dataset.category!==b.dataset.filter)}));
function activatePanel(panel){$$('.work-panel').forEach(p=>{const active=p===panel;p.classList.toggle('active',active);p.querySelector('button').setAttribute('aria-expanded',active);p.querySelector('.work-body').inert=!active})}$$('.work-panel').forEach(p=>{p.querySelector('button').addEventListener('click',()=>activatePanel(p));p.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse'&&innerWidth>760&&!p.contains(document.activeElement))activatePanel(p)})});
const card=$('.id-card');function flip(){card.classList.toggle('flipped');card.setAttribute('aria-pressed',card.classList.contains('flipped'))}card.addEventListener('click',flip);card.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse'&&!reduced&&!card.classList.contains('flipped'))flip()});$('.id-wrap').addEventListener('pointermove',e=>{if(reduced)return;const r=e.currentTarget.getBoundingClientRect();$('.id-swing').style.setProperty('--swing',`${((e.clientX-r.left)/r.width-.5)*12}deg`)});$('.id-wrap').addEventListener('pointerleave',()=>$('.id-swing').style.setProperty('--swing','3deg'));
const video=$('#hero-video'),sound=$('.sound');let heroVisible=true,audioWanted=false,blocked=true,autoTried=false;function updateSound(){sound.classList.toggle('blocked',blocked);sound.setAttribute('aria-pressed',audioWanted&&!video.muted);sound.setAttribute('aria-label',video.muted?'영상 소리 켜기':'영상 소리 끄기');sound.firstElementChild.textContent=video.muted?'▶':'❚❚';$('.sound-status').textContent=video.muted?'소리 켜기':'소리 재생 중'}async function enableAudio(){if(!heroVisible)return;audioWanted=true;video.muted=false;try{await video.play();blocked=false}catch{video.muted=true;audioWanted=false;blocked=true;video.play().catch(()=>{})}updateSound()}
// Some browsers decode VP9 video without its alpha plane. Use the paper-colored MP4 there.
function checkVideoAlpha(){if(!video.currentSrc.endsWith('intro-cutout.webm'))return;try{const canvas=document.createElement('canvas');canvas.width=canvas.height=1;const context=canvas.getContext('2d',{willReadFrequently:true});context.drawImage(video,0,0,1,1,0,0,1,1);if(context.getImageData(0,0,1,1).data[3]>240){video.src='hero/intro-paper.mp4';video.load();if(heroVisible&&!document.hidden)video.play().catch(()=>{})}}catch{}}
video.addEventListener('loadeddata',checkVideoAlpha);if(video.readyState>=2)checkVideoAlpha();
video.addEventListener('playing',()=>{if(autoTried)return;autoTried=true;enableAudio()},{once:true});video.play().catch(()=>{});function gesture(e){if(e.target.closest('.sound'))return;if(blocked&&heroVisible)enableAudio()}document.addEventListener('pointerdown',gesture);document.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key))gesture(e)});sound.addEventListener('click',()=>{if(video.muted)enableAudio();else{audioWanted=false;video.muted=true;blocked=false;updateSound()}});new IntersectionObserver(entries=>{heroVisible=entries[0].intersectionRatio>=.35;if(!heroVisible)video.pause();else if(!document.hidden){video.muted=!audioWanted;video.play().catch(()=>{video.muted=true;blocked=true;updateSound()})}},{threshold:[0,.35,1]}).observe($('#hero'));document.addEventListener('visibilitychange',()=>{if(document.hidden)video.pause();else if(heroVisible)video.play().catch(()=>{})});
let menuOpener=null;function closeMenu(){$('#mobile-menu').hidden=true;$('.menu-toggle').setAttribute('aria-expanded','false');document.body.classList.remove('menu-open');lenis?.start();menuOpener?.focus()}$('.menu-toggle').addEventListener('click',()=>{menuOpener=document.activeElement;$('#mobile-menu').hidden=false;$('.menu-toggle').setAttribute('aria-expanded','true');document.body.classList.add('menu-open');lenis?.stop();$('#close-menu').focus()});$('#close-menu').addEventListener('click',closeMenu);$$('#mobile-menu a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if($('#mobile-menu').hidden)return;if(e.key==='Escape')closeMenu();if(e.key==='Tab'){const focusables=$$('#mobile-menu button, #mobile-menu a');const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});$('.fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{$('.fullscreen').title='이 브라우저에서는 전체화면을 지원하지 않습니다.'}});
$('.copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(CONTACT.email);$('.copy').textContent='복사됨 ✓'}catch{$('.copy').textContent='이메일을 선택해 복사해 주세요';const range=document.createRange();range.selectNodeContents($('.email'));const selection=getSelection();selection.removeAllRanges();selection.addRange(range)}});
const counted=new Set();const counterObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(!e.isIntersecting||counted.has(e.target))return;counted.add(e.target);const target=+e.target.dataset.count;if(reduced)return;const start=performance.now();function step(t){const progress=Math.min((t-start)/1400,1);e.target.textContent=Math.round(target*(1-(1-progress)**3));if(progress<1)requestAnimationFrame(step)}requestAnimationFrame(step)}),{threshold:.7});$$('[data-count]').forEach(e=>counterObserver.observe(e));
let scheduled=false;function scrollFrame(){scheduled=false;const y=scrollY,max=document.documentElement.scrollHeight-innerHeight;$('.progress').style.transform=`scaleX(${max?y/max:0})`;$('#header').classList.toggle('scrolled',y>40);let current='';for(const [id] of NAV){if($('#'+id).getBoundingClientRect().top<innerHeight*.45)current=id}$$('nav a').forEach(a=>{const active=a.hash==='#'+current;a.classList.toggle('active',active);if(active){a.setAttribute('aria-current','location');$('.nav-indicator').style.transform=`translateX(${a.offsetLeft+a.offsetWidth/2-7}px)`}else a.removeAttribute('aria-current')});$('.nav-indicator').style.opacity=current?'1':'0';const timeline=$('.timeline'),tr=timeline.getBoundingClientRect();timeline.style.setProperty('--timeline',Math.max(0,Math.min(1,(innerHeight*.75-tr.top)/tr.height)));$$('.timeline-item').forEach(e=>e.classList.toggle('lit',e.getBoundingClientRect().top<innerHeight*.75));if(!reduced){const section=$('#achievements'),r=section.getBoundingClientRect(),track=$('.achievement-track');const progress=Math.max(0,Math.min(1,-r.top/(section.offsetHeight-innerHeight)));const travel=Math.max(0,track.scrollWidth-$('.achievements .container').clientWidth);track.style.transform=`translateX(${-progress*travel}px)`}}function schedule(){if(!scheduled){scheduled=true;requestAnimationFrame(scrollFrame)}}addEventListener('scroll',schedule,{passive:true});addEventListener('resize',schedule);scrollFrame();
